using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Reflection;using System.Web.Script.Serialization;using System.Windows.Forms;using VirgilPatch;
class StartupRepairTests {
 static string root;static int passed;static JavaScriptSerializer js=new JavaScriptSerializer();
 static void Assert(bool b,string why){if(!b)throw new Exception(why);}static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Expected rejection");}static void Test(string n,Action a){a();passed++;Console.WriteLine("PASS "+n);}
 static State Fresh(){string area=Path.Combine(root,Guid.NewGuid().ToString("N"));Config.StateDir=Path.Combine(area,"state");var s=new State{patches_dir=Path.Combine(area,"Patches")};Directory.CreateDirectory(s.patches_dir);return s;}
 static string Seed(State s,string key,bool mapped,params string[] names){string folder=mapped?FolderMigration.Canonical(key):key;string dir=Path.Combine(s.patches_dir,folder);Directory.CreateDirectory(dir);if(mapped)s.install_folders[key]=folder;var rows=new List<object>();uint id=100;foreach(string name in names){byte[] bytes=Encoding.UTF8.GetBytes(name+" fixture content");string path=Path.Combine(dir,name.ToLowerInvariant().Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,bytes);rows.Add(new{file=name,id=id++});s.installed[key+"/"+name]=RepairSource.Sha(bytes);}string meta=Path.Combine(dir,"patch.json");File.WriteAllText(meta,js.Serialize(new{name=key,files=rows}));s.installed[key+"/patch.json"]=Updater.BlobSha(meta);return dir;}
 static int Repair(State s,List<string> log=null,Func<bool> running=null){return StartupCasingRepair.Apply(s,m=>{if(log!=null)log.Add(m);},default(CancellationToken),running??(()=>false));}
 static bool Exact(string dir,string rel){foreach(string part in rel.Split('/')){if(!Directory.EnumerateFileSystemEntries(dir).Any(p=>Path.GetFileName(p)==part))return false;dir=Path.Combine(dir,part);}return true;}
 static void Pump(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(15);while(!done()){if(DateTime.UtcNow>end)throw new Exception("Background scan timed out");Application.DoEvents();Thread.Sleep(10);}Application.DoEvents();}
 [STAThread]static int Main(string[] a){try{root=Path.GetFullPath(a[0]);Directory.CreateDirectory(root);Config.StartAmbienceMuted=true;
 Test("all-managed-patches-models-textures-and-nested-folders",delegate{var s=Fresh();string one=Seed(s,"!Chronicles-TexturePatch(3.2.0)",true,"World/Castle.wmo","Creature/Dragon.m2","Creature/Dragon00.skin","Textures/Stone.BLP");string two=Seed(s,"Chronicles-Classic",true,"Doodads/Tree.M2","DBFilesClient/Test.db2");string meta=File.ReadAllText(Path.Combine(one,"patch.json"));Assert(Repair(s)==6,"Not every model type/patch repaired");foreach(string n in new[]{"World/Castle.wmo","Creature/Dragon.m2","Creature/Dragon00.skin","Textures/Stone.BLP"})Assert(Exact(one,n),"Wrong spelling "+n);Assert(Exact(two,"Doodads/Tree.M2")&&Exact(two,"DBFilesClient/Test.db2"),"Other patch not repaired");Assert(meta==File.ReadAllText(Path.Combine(one,"patch.json")),"Metadata changed");foreach(var e in s.installed){int slash=e.Key.IndexOf('/');string key=e.Key.Substring(0,slash),name=e.Key.Substring(slash+1);Assert(Updater.BlobSha(Path.Combine(s.patches_dir,s.install_folders[key],name))==e.Value,"File bytes changed");}Assert(Repair(s)==0,"Check not idempotent");});
 Test("legacy-managed-folders-without-migration-map-are-covered",delegate{var s=Fresh();string d=Seed(s,"LegacyPatch",false,"Dragon.M2");Assert(Repair(s)==1&&Exact(d,"Dragon.M2"),"Legacy managed patch skipped");});
 Test("modified-or-missing-files-are-reported-while-other-models-repair",delegate{var s=Fresh();string d=Seed(s,"Example",false,"Modified.wmo","Missing.wmo","Good.wmo");File.WriteAllText(Path.Combine(d,"modified.wmo"),"development edit");File.Delete(Path.Combine(d,"missing.wmo"));var log=new List<string>();Assert(Repair(s,log)==1&&Exact(d,"Good.wmo")&&Exact(d,"modified.wmo"),"Modified file changed or good file skipped");Assert(log.Any(m=>m.Contains("missing 1"))&&log.Any(m=>m.Contains("manual verification")),"Missing/deferred details absent");});
 Test("unmanaged-patches-are-checked-and-reported-without-renaming",delegate{var s=Fresh();string d=Seed(s,"LocalDevelopment",false,"Local.M2");s.installed.Clear();var log=new List<string>();Assert(Repair(s,log)==0&&Exact(d,"local.m2"),"Unmanaged file renamed");Assert(log.Any(m=>m.Contains("Local.M2")&&m.Contains("manual verification")),"Unmanaged mismatch was not checked/reported");});
 Test("metadata-capitalization-is-repaired-after-checksum-verification",delegate{var s=Fresh();string d=Seed(s,"Example",false,"model.m2");File.Move(Path.Combine(d,"patch.json"),Path.Combine(d,"temp"));File.Move(Path.Combine(d,"temp"),Path.Combine(d,"Patch.JSON"));Assert(Repair(s)==1&&Exact(d,"patch.json"),"Metadata spelling not repaired");});
 Test("invalid-manifest-does-not-block-other-valid-patches",delegate{var s=Fresh();string bad=Seed(s,"Broken",false,"Bad.M2"),good=Seed(s,"Good",false,"Tree.M2");string p=Path.Combine(bad,"patch.json");File.WriteAllText(p,"{\"files\":[],"+File.ReadAllText(p).Substring(1));var log=new List<string>();Assert(Repair(s,log)==1&&Exact(bad,"bad.m2")&&Exact(good,"Tree.M2"),"Malformed patch mutated or blocked other patches");Assert(log.Any(m=>m.Contains("deferred for Broken")),"Bad manifest not reported");});
 Test("traversal-duplicate-ids-and-inconsistent-directory-casing-rejected",delegate{foreach(string json in new[]{"{\"files\":[{\"file\":\"../Outside.m2\",\"id\":1}]}","{\"files\":[{\"file\":\"Bad.M2\",\"id\":1},{\"file\":\"Other.M2\",\"id\":1}]}","{\"files\":[{\"file\":\"World/A.m2\",\"id\":1},{\"file\":\"world/B.m2\",\"id\":2}]}"}){var s=Fresh();string d=Seed(s,"Broken",false,"Bad.M2");File.WriteAllText(Path.Combine(d,"patch.json"),json);Assert(Repair(s)==0&&Exact(d,"bad.m2"),"Unsafe manifest changed files");}});
 Test("concurrent-lock-cancellation-and-game-running-defer-safely",delegate{var s=Fresh();string d=Seed(s,"Example",false,"Dragon.M2");using(Updater.AcquirePatchLock(s.patches_dir)){Reject(()=>Repair(s));}var c=new CancellationTokenSource();c.Cancel();Reject(()=>StartupCasingRepair.Apply(s,m=>{},c.Token,()=>false));Assert(Repair(s,null,()=>true)==0&&Exact(d,"dragon.m2"),"Running game allowed rename");int checks=0;Assert(Repair(s,null,()=>++checks>1)==0&&Exact(d,"dragon.m2"),"Game starting during scan allowed rename");Assert(Repair(s)==1,"Deferred repair could not retry");});
 Test("read-only-inventory-reports-mismatches-without-renaming",delegate{var s=Fresh();string d=Seed(s,"Example",false,"Dragon.M2");var log=new List<string>();Assert(StartupCasingRepair.Apply(s,log.Add,default(CancellationToken),()=>false,false)==0&&Exact(d,"dragon.m2"),"Read-only check renamed files");Assert(log.Any(m=>m.Contains("casing mismatches 1")),"Read-only mismatch not reported");});
 Test("correct-filenames-do-not-rehash-or-open-large-assets",delegate{var s=Fresh();string d=Seed(s,"Example",false,"lower.m2");using(var locked=new FileStream(Path.Combine(d,"lower.m2"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){Assert(Repair(s)==0,"Exact-name asset unnecessarily opened");}});
 Test("actual-window-runs-background-scan-without-update-click",delegate{var s=Fresh();string d=Seed(s,"Example",false,"NewModel.M2");s.Save();string state=File.ReadAllText(Path.Combine(Config.StateDir,"state.json"));string empty=Path.Combine(root,"empty-source");Directory.CreateDirectory(empty);using(var form=new MainForm(new FolderSource(empty),null,true)){form.StartupGameRunning=()=>false;form.Opacity=0;form.Show();Pump(()=>!(bool)typeof(MainForm).GetField("isBusy",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form));Assert(Exact(d,"NewModel.M2"),"Window launch failed to repair arbitrary model");Assert(File.ReadAllText(Path.Combine(Config.StateDir,"state.json"))==state,"Filename scan rewrote saved state");form.Close();}});
 Console.WriteLine("TOTAL "+passed+" general automatic filename cases passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
